mapper.select:
select count(*)
from schedule
where empnum = #{empNum}
  and codebid = 'VACATION'
  and starttime <= #{endTime}
  and endtime   >= #{startTime}

select count(*)
from schedule
where empnum = #{empNum}
  and codebid = 'VACATION'
  and shnum  <> #{shNum}
  and starttime <= #{endTime}
  and endtime   >= #{startTime}

select s.shnum, s.empnum, s.codebid, s.starttime, s.endtime, s.memo, s.memnum, e.empname, cb.name as codebname, m.memname from schedule s join employee e on s.empnum = e.empnum left join codeb cb on s.codebid = cb.codebid left join member m on s.memnum = m.memnum
s.codebid = #{codeBid}
and ( lower(e.empname) like concat('%', lower(#{keyword}), '%') or lower(ifnull(m.memname,''))like concat('%', lower(#{keyword}), '%') or lower(ifnull(s.memo,'')) like concat('%', lower(#{keyword}), '%') )
order by s.starttime desc limit #{limit} offset #{offset}

select count(*) from schedule s join employee e on s.empnum = e.empnum left join codeb cb on s.codebid = cb.codebid left join member m on s.memnum = m.memnum
s.codebid = #{codeBid}
and ( lower(e.empname) like concat('%', lower(#{keyword}), '%') or lower(ifnull(m.memname,''))like concat('%', lower(#{keyword}), '%') or lower(ifnull(s.memo,'')) like concat('%', lower(#{keyword}), '%') )

mapper.update:

update schedule s
   set s.empnum    = #{empNum,    jdbcType=NUMERIC}
     , s.codebid   = #{codeBid,   jdbcType=VARCHAR}
     , s.starttime = #{startTime, jdbcType=TIMESTAMP}
     , s.endtime   = #{endTime,   jdbcType=TIMESTAMP}
     , s.memnum    = #{memNum,    jdbcType=NUMERIC}
     , s.memo      = #{memo,      jdbcType=VARCHAR}
 where s.shnum = #{shNum, jdbcType=NUMERIC}
   and not exists (
         select 1
           from schedule x
          where x.empnum = #{empNum, jdbcType=NUMERIC}
            and x.shnum <> #{shNum, jdbcType=NUMERIC}  -- 자기 자신 제외
            and #{startTime, jdbcType=TIMESTAMP} < x.endtime
            and x.starttime < #{endTime, jdbcType=TIMESTAMP}
            and (
                  /* PT는 PT/VACATION과만 충돌 */
                  (#{codeBid, jdbcType=VARCHAR} = 'SCHEDULE-PT' and x.codebid in ('SCHEDULE-PT','VACATION'))
               or /* ETC는 VACATION과만 충돌 */
                  (#{codeBid, jdbcType=VARCHAR} like 'ETC-%'       and x.codebid = 'VACATION')
               or /* VACATION은 모든 코드와 충돌 */
                  (#{codeBid, jdbcType=VARCHAR} = 'VACATION')
                )
       )
